# -*- coding: utf-8 -*-
"""Build the merged prompt review without modifying prompt source files."""
from pathlib import Path
from html import escape, unescape
import difflib
import hashlib
import json
import re

ROOT = Path(__file__).resolve().parent
data = json.loads((ROOT / 'review-data.json').read_text())


def compare(before, after):
    left, right, hunks = [], [], []
    a, b = before.splitlines(True), after.splitlines(True)
    for tag, i, j, k, l in difflib.SequenceMatcher(None, a, b, autojunk=False).get_opcodes():
        x, y = ''.join(a[i:j]), ''.join(b[k:l])
        if tag == 'equal':
            left.append(escape(x)); right.append(escape(y))
            continue
        hx, hy = [], []
        for t, ai, aj, bi, bj in difflib.SequenceMatcher(None, x, y, autojunk=False).get_opcodes():
            xx, yy = escape(x[ai:aj]), escape(y[bi:bj])
            hx.append(xx if t == 'equal' else '<span class="del-mark">' + xx + '</span>' if xx else '')
            hy.append(yy if t == 'equal' else '<span class="add-mark">' + yy + '</span>' if yy else '')
        hx, hy = ''.join(hx), ''.join(hy)
        left.append(hx); right.append(hy)
        hunks.append({'kind': tag, 'old': hx, 'new': hy})
    left, right = ''.join(left), ''.join(right)
    assert unescape(re.sub(r'</?span\b[^>]*>', '', left)) == before
    assert unescape(re.sub(r'</?span\b[^>]*>', '', right)) == after
    return {'old': left, 'new': right, 'hunks': hunks}


for f in data['files']:
    f['diffDev'] = compare(f['dev'], f['final'])
    f['diffPrevious'] = compare(f['previous'], f['final'])

